import type { Meta, StoryObj } from '@storybook/preact-vite';
import { expect } from 'storybook/test';
import {
  LiveRegion as component,
  LiveRegionProps,
} from '@adobe-commerce/elsie/components/LiveRegion';

/**
 * `LiveRegion` renders a visually-hidden, always-mounted live region element
 * that announces content changes to screen readers without requiring focus movement.
 *
 * It uses `aria-live` and `aria-atomic` exclusively — no explicit `role` is set,
 * avoiding the double-announcement issue that arises when both a semantic role
 * and `aria-live` are present on the same element.
 *
 * Use it alongside loading indicators or whenever content updates dynamically,
 * to satisfy **WCAG 4.1.3 Status Messages**.
 *
 * The element is visually hidden — the Storybook preview renders
 * it with a visible outline for demonstration purposes only.
 */
const meta: Meta<LiveRegionProps> = {
  title: 'Components/LiveRegion',
  component,
  decorators: [
    (Story) => (
      <div>
        <p
          style={{ fontSize: '0.875rem', color: '#666', marginBottom: '1rem' }}
        >
          The live region is visually hidden. The dashed outline below is for
          demonstration only.
        </p>
        <div
          style={{
            outline: '2px dashed #6e6e6e',
            padding: '0.5rem',
            position: 'relative',
            minHeight: '2rem',
          }}
        >
          <Story />
        </div>
      </div>
    ),
  ],
  argTypes: {
    message: {
      description:
        'The text announced to screen readers. Pass an empty string to clear a previous announcement without unmounting the element.',
      table: {
        type: { summary: 'string' },
        defaultValue: { summary: '""' },
      },
      control: 'text',
    },
    politeness: {
      description:
        'Controls announcement urgency. `"polite"` waits for the user to finish; `"assertive"` interrupts immediately.',
      table: {
        type: { summary: '"polite" | "assertive"' },
        defaultValue: { summary: '"polite"' },
      },
      options: ['polite', 'assertive'],
      control: 'radio',
    },
    className: {
      description: 'Additional CSS class merged with `dropin-live-region`.',
      table: {
        type: { summary: 'string' },
      },
      control: 'text',
    },
  },
};
export default meta;

type Story = StoryObj<LiveRegionProps>;

/**
 * ```tsx
 * <LiveRegion message="Loading order summary" />
 * ```
 */
export const LiveRegion: Story = {
  tags: ['isHidden'],
  args: {
    message: 'Loading order summary',
    politeness: 'polite',
  },
};

/**
 * Default state — empty message. The region is mounted but silent.
 * Browsers and AT will announce nothing until `message` changes to a non-empty string.
 *
 * ```tsx
 * <LiveRegion />
 * ```
 */
export const Empty: Story = {
  args: {
    message: '',
  },
  play: async ({ canvasElement }) => {
    const region = canvasElement.querySelector<HTMLElement>(
      '[aria-live="polite"]',
    )!;
    await expect(region).toBeInTheDocument();
    await expect(region).toHaveAttribute('aria-live', 'polite');
    await expect(region).toHaveAttribute('aria-atomic', 'true');
    await expect(region.textContent).toBe('');
  },
};

/**
 * Polite announcement — the default. Screen readers finish the current sentence
 * before reading the status message.
 *
 * ```tsx
 * <LiveRegion message="3 items added to cart" />
 * ```
 */
export const Polite: Story = {
  args: {
    message: '3 items added to cart',
    politeness: 'polite',
  },
  play: async ({ canvasElement }) => {
    const region = canvasElement.querySelector<HTMLElement>(
      '[aria-live="polite"]',
    )!;
    await expect(region).toHaveAttribute('aria-live', 'polite');
    await expect(region.textContent).toBe('3 items added to cart');
  },
};

/**
 * Assertive announcement — interrupts the screen reader immediately.
 * Reserve for time-sensitive errors or critical state changes.
 *
 * ```tsx
 * <LiveRegion message="Payment failed. Please try again." politeness="assertive" />
 * ```
 */
export const Assertive: Story = {
  args: {
    message: 'Payment failed. Please try again.',
    politeness: 'assertive',
  },
  play: async ({ canvasElement }) => {
    const region = canvasElement.querySelector<HTMLElement>(
      '[aria-live="assertive"]',
    )!;
    await expect(region).toHaveAttribute('aria-live', 'assertive');
    await expect(region).toHaveAttribute('aria-atomic', 'true');
    await expect(region.textContent).toBe('Payment failed. Please try again.');
  },
};

/**
 * Loading state pattern — pair a `LiveRegion` with a visual loading indicator.
 * The `LiveRegion` is always mounted; only its `message` changes.
 *
 * ```tsx
 * <LiveRegion message={loading ? 'Loading shipping methods' : ''} />
 * {loading && <ProgressSpinner />}
 * ```
 */
export const LoadingPattern: Story = {
  args: {
    message: 'Loading shipping methods',
    politeness: 'polite',
  },
  play: async ({ canvasElement }) => {
    const region = canvasElement.querySelector<HTMLElement>(
      '[aria-live="polite"]',
    )!;
    await expect(region).toBeInTheDocument();
    await expect(region.textContent).toBe('Loading shipping methods');
  },
};
